package org.agentfrc.lesson;
import java.nio.file.*;import java.security.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
public class PassiveUnloadTest {
 static Path out;static Properties input=new Properties(),results=new Properties();static byte[] raw;static double[] max=new double[11];
 static String sha(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}static double d(String k){return Double.parseDouble(input.getProperty(k));}
 @BeforeAll static void hal()throws Exception{out=Path.of(Objects.requireNonNull(System.getenv("FRC_PASSIVE_OUTPUT"),"Fresh native-bound runner required"));raw=Files.readAllBytes(out.resolve("input.properties"));input.load(new java.io.ByteArrayInputStream(raw));assertEquals("frc-passive-unload/v1",input.getProperty("passiveSchema"));assertEquals(input.getProperty("passiveExperimentSha256"),sha(Files.readAllBytes(out.resolve("experiment.json"))));for(String v:List.of("compressed","nominal"))assertEquals(input.getProperty(v+"PropertiesSha256"),sha(Files.readAllBytes(out.resolve("baseline/"+v+"/properties.json"))));edu.wpi.first.hal.HAL.initialize(500,0);}
 static PassiveUnloadPlant.Config config(){return new PassiveUnloadPlant.Config(d("massKg"),d("sphereRadiusM"),d("rollerRadiusM"),d("rollerInertiaKgM2"),d("rollerZM"),d("wallXM"),d("gear"),.8);}
 @AfterAll static void writeResults()throws Exception{results.setProperty("inputSha256",sha(raw));for(Class<?> c:List.of(PassiveUnloadPlant.class,PassiveUnloadController.class,PassiveUnloadRig.class,NipExitAssessor.class))results.setProperty(c.getSimpleName()+"ClassSha256",sha(c.getResourceAsStream(c.getSimpleName()+".class").readAllBytes()));String[] names={"xM","zM","vxMps","vzMps","sphereRadps","rollerRadps","busVolts","batteryAmps","normalLossJ","frictionLossJ","mechanicalResidualJ"};for(int j=0;j<11;j++)results.setProperty("maxDifference."+names[j],Double.toString(max[j]));results.setProperty("engineeringAcceptance","blocked");results.setProperty("vendorNeutralModeExecuted","false");results.setProperty("capture","unestablished");try(var s=Files.newOutputStream(out.resolve("passive-result.properties"),StandardOpenOption.CREATE_NEW)){results.store(s,"Separate ideal passive-unload hypothesis, not REV firmware");}}
 static double[] values(PassiveUnloadPlant.Sample a){return new double[]{a.x(),a.z(),a.vx(),a.vz(),a.sphereOmega(),a.rollerOmega(),a.bus(),a.current(),a.normalLoss(),a.frictionLoss(),a.mechanicalResidual()};}
 static double[][] trajectory(PassiveUnloadPlant.NeutralMode mode,int delay,int steps)throws Exception{double[][] rows=new double[195][11];String id=mode+"-delay"+delay+"-steps"+steps;StringBuilder csv=new StringBuilder("intervalStartS,intervalEndS,xM,zM,vxMps,vzMps,sphereOmega,rollerOmega,busVolts,batteryAmps,normalLossJ,frictionLossJ,residualJ,emfVolts,armatureAmps,motorTorque,commandedMode,appliedMode,phase,verifiedModelNipExit\n");try(var rig=new PassiveUnloadRig(config(),mode,delay)){for(int i=0;i<rows.length;i++){var a=rig.step(true,i>=60,steps);rows[i]=values(a);assertTrue(Math.abs(a.mechanicalResidual())<1e-5);if(a.appliedMode()==PassiveUnloadPlant.NeutralMode.OPEN){assertEquals(0,a.armatureAmps());assertEquals(0,a.current());assertEquals(0,a.electromagneticTorque());}if(mode==PassiveUnloadPlant.NeutralMode.OPEN&&i==60)assertEquals(delay==0?PassiveUnloadPlant.NeutralMode.OPEN:PassiveUnloadPlant.NeutralMode.BRAKE,a.appliedMode());if(mode==PassiveUnloadPlant.NeutralMode.OPEN&&i==61)assertEquals(PassiveUnloadPlant.NeutralMode.OPEN,a.appliedMode());csv.append(i*.02).append(',').append((i+1)*.02).append(',');for(double v:rows[i])csv.append(v).append(',');csv.append(a.backEmfVolts()).append(',').append(a.armatureAmps()).append(',').append(a.electromagneticTorque()).append(',').append(rig.controller.commandedMode()).append(',').append(a.appliedMode()).append(',').append(rig.controller.phase()).append(',').append(rig.assessor.verified()).append('\n');}
  boolean expected=mode==PassiveUnloadPlant.NeutralMode.OPEN;assertEquals(expected,rig.assessor.verified());assertEquals(expected,rig.controller.exitSequence());assertFalse(rig.assessor.recontact());results.setProperty(id+".outcome",rig.assessor.verified()?"verified-model-local-nip-exit":"no-exit-within-horizon");results.setProperty(id+".sensorSequence",Boolean.toString(rig.controller.exitSequence()));results.setProperty(id+".verificationTime",Double.isFinite(rig.assessor.verificationTime())?Double.toString(rig.assessor.verificationTime()):"unobserved");}Files.writeString(out.resolve(id+".csv"),csv,StandardOpenOption.CREATE_NEW);return rows;}
 @Test void pairedNativeExperimentAndRefinement()throws Exception{double[][] prefix=null;for(var mode:PassiveUnloadPlant.NeutralMode.values())for(int delay=0;delay<=1;delay++){var coarse=trajectory(mode,delay,200);var fine=trajectory(mode,delay,400);if(mode==PassiveUnloadPlant.NeutralMode.OPEN)assertEquals(Double.parseDouble(results.getProperty(mode+"-delay"+delay+"-steps200.verificationTime")),Double.parseDouble(results.getProperty(mode+"-delay"+delay+"-steps400.verificationTime")),.00021,"Integrated exit timing refinement");if(prefix==null)prefix=coarse;for(int i=0;i<60;i++)assertArrayEquals(prefix[i],coarse[i],0,"Exact paired pre-unload state");for(int i=0;i<coarse.length;i++)for(int j=0;j<11;j++)max[j]=Math.max(max[j],Math.abs(coarse[i][j]-fine[i][j]));}double[] tolerance={1e-5,1e-5,1e-4,1e-4,1e-4,1e-4,1e-4,1e-3,1e-5,1e-5,1e-5};for(int j=0;j<11;j++)assertTrue(max[j]<tolerance[j],"Refinement SI component "+j);}
 @Test void baselinePrefixMatchesOriginal(){var c=config();double[][] old=new double[60][6];try(var rig=new FuelIntakeRig(new FuelIntakePlant.Config(c.mass(),c.radius(),c.rollerRadius(),c.rollerInertia(),c.rollerZ(),c.wallX(),c.gear(),c.rollerMu()),1)){for(int i=0;i<60;i++){var a=rig.step(true,false,200);old[i]=new double[]{a.x(),a.z(),a.vx(),a.vz(),a.sphereOmega(),a.rollerOmega()};}}try(var rig=new PassiveUnloadRig(c,PassiveUnloadPlant.NeutralMode.OPEN,1)){for(int i=0;i<60;i++)assertArrayEquals(old[i],Arrays.copyOf(values(rig.step(true,false,200)),6),0);}}
 @Test void openRequiresNeutralAndPreservesState(){var p=new PassiveUnloadPlant(config(),-.06,.075,.15);for(int i=0;i<100;i++)p.step(-.12,.0001,PassiveUnloadPlant.NeutralMode.BRAKE);var a=p.sample(0);p.setMode(PassiveUnloadPlant.NeutralMode.OPEN,0);var b=p.sample(0);assertEquals(a.x(),b.x());assertEquals(a.rollerOmega(),b.rollerOmega());assertEquals(a.mechanicalResidual(),b.mechanicalResidual());assertEquals(0,b.armatureAmps());assertEquals(0,b.current());assertEquals(0,b.electromagneticTorque());assertNotEquals(0,b.backEmfVolts());assertThrows(IllegalArgumentException.class,()->p.step(.01,.0001,PassiveUnloadPlant.NeutralMode.OPEN));}
 @Test void disableOverridesPendingAndAppliedOpen(){for(int delay=0;delay<=1;delay++)try(var rig=new PassiveUnloadRig(config(),PassiveUnloadPlant.NeutralMode.OPEN,delay)){for(int i=0;i<60;i++)rig.step(true,false,200);rig.step(true,true,200);rig.step(false,true,200);assertEquals(PassiveUnloadController.Phase.FAULT,rig.controller.phase());assertEquals(PassiveUnloadPlant.NeutralMode.BRAKE,rig.appliedMode());rig.step(true,true,200);assertEquals(PassiveUnloadController.Phase.FAULT,rig.controller.phase());}}
 @Test void stuckAndMissingBeamNeverReportsSuccess(){for(int fault:new int[]{1,2,3})try(var rig=new PassiveUnloadRig(config(),PassiveUnloadPlant.NeutralMode.OPEN,0,fault,1)){try{for(int i=0;i<195;i++)rig.step(true,i>=60,200);}catch(IllegalArgumentException e){assertTrue(e.getMessage().contains("Unsupported regeneration"));}assertNotEquals(PassiveUnloadController.Phase.DONE,rig.controller.phase());}}
 @Test void corruptedEncoderStopsCandidate(){try(var rig=new PassiveUnloadRig(config(),PassiveUnloadPlant.NeutralMode.OPEN,0,0,-1)){for(int i=0;i<5;i++)rig.step(true,false,200);assertEquals(PassiveUnloadController.Phase.FAULT,rig.controller.phase());}}
 @Test void assessorRequiresSeparationAndRejectsRecontact(){var untouched=new NipExitAssessor(.1861,.1131);untouched.observe(0,-.1,.075,-.1,0);assertThrows(IllegalStateException.class,untouched::arm);assertFalse(untouched.verified());var a=new NipExitAssessor(.1861,.1131);a.observe(0,0,.075,0,0);a.arm();a.observe(.1,-.1,.075,.1,0);assertFalse(a.verified());assertThrows(IllegalArgumentException.class,()->a.observe(.1,-.1,.075,-.1,0));assertThrows(IllegalArgumentException.class,()->a.observe(Double.NaN,-.1,.075,-.1,0));a.observe(.2,-.1,.075,-.1,0);a.observe(.41,-.12,.075,-.1,0);assertTrue(a.verified());a.observe(.42,0,.075,0,0);assertFalse(a.verified());assertTrue(a.recontact());}
 @Test void drivenRegenerationStillRejected(){var p=new PassiveUnloadPlant(config(),-.06,.075,.15);var e=assertThrows(IllegalArgumentException.class,()->{for(int i=0;i<10000;i++)p.step(-.12,.0001,PassiveUnloadPlant.NeutralMode.BRAKE);});assertTrue(e.getMessage().contains("Unsupported regeneration"));}
}
